/**
 * Prismatic Liquid Glass — Interactive React / Next.js Component
 * Generated by Shader Studio (https://shaderstudio.com)
 * 
 * Features:
 * - ⚡ 60 FPS WebGL2 procedural rendering
 * - 📐 Container-responsive with ResizeObserver
 * - 🔋 Auto-pauses offscreen (0% CPU/GPU via IntersectionObserver & visibilitychange)
 * - 🎛️ 3D Gyroscopic Spring Card Tilt (zero React re-renders)
 * - ♿ Accessible semantic typography overlay
 */

'use client'; // Required for Next.js App Router

import React, { useEffect, useRef } from 'react';

export interface PrismaticLiquidGlassCardProps {
  badge?: string;
  title?: string;
  subtitle?: string;
  cta?: string;
  logoSrc?: string;
  imageSrc?: string;
  colorA?: string;
  colorB?: string;
  colorC?: string;
  speed?: number;
  interactive?: boolean;
  tilt?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

const FRAG = "#version 300 es\nprecision highp float;\nprecision highp int;\nout vec4 fragColor;\n\n// ── Active System Uniforms\nuniform float u_time;\nuniform vec2  u_resolution;\nuniform float u_glass_scale;\nuniform float u_dispersion;\nuniform float u_liquid_flow;\nuniform float u_caustic_power;\nuniform float u_refract_depth;\nuniform float u_speed;\nuniform float u_scale;\nuniform float u_rotation;\nuniform float u_cx;\nuniform float u_cy;\nuniform float u_exposure;\nuniform float u_hue;\nuniform float u_saturation;\nuniform float u_brightness;\nuniform float u_contrast;\nuniform vec3 u_colorA;\nuniform vec3 u_colorB;\nuniform vec3 u_colorC;\nmat2 rot(float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }\nvec2 rot(vec2 p, float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c) * p; }\n\nvec3 hsv2rgb(vec3 c){\n  vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);\n  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);\n  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);\n}\nvec3 rgb2hsv(vec3 c){\n  vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);\n  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));\n  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));\n  float d = q.x - min(q.w, q.y);\n  float e = 1.0e-10;\n  return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);\n}\n\n\n// ═══════ User shader body — evaluates raw scene colour at uv ═══════\nvec3 renderScene(vec2 uv){\n  uv = rot(u_rotation) * uv;\n  uv = uv * u_scale + vec2(u_cx, u_cy);\n  float t = u_time * u_speed;\nvec2 p = uv * u_glass_scale;\n  float time = t * 0.35 * u_liquid_flow;\n  \n  // High-order harmonic liquid wave field\n  vec2 q1 = p + vec2(sin(p.y * 1.45 + time * 0.8), cos(p.x * 1.35 - time * 0.65)) * 0.55;\n  vec2 q2 = p + vec2(cos(q1.y * 1.25 - time * 0.75), sin(q1.x * 1.4 + time * 0.85)) * 0.45;\n  \n  float h0 = sin(q2.x * 1.8 + time * 0.9) * 0.45 + cos(q2.y * 1.9 - time * 0.75) * 0.45;\n  h0 += sin((q2.x + q2.y) * 1.5 + time * 1.2) * 0.22;\n  h0 += cos(length(q1) * 2.2 - time * 1.4) * 0.14;\n  \n  // Numerical gradient for accurate physical surface normal\n  vec2 eps = vec2(0.008, 0.0);\n  vec2 qX = (p + eps.xy) + vec2(sin((p.y + eps.y) * 1.45 + time * 0.8), cos((p.x + eps.x) * 1.35 - time * 0.65)) * 0.55;\n  vec2 qX2 = (p + eps.xy) + vec2(cos(qX.y * 1.25 - time * 0.75), sin(qX.x * 1.4 + time * 0.85)) * 0.45;\n  float hX = sin(qX2.x * 1.8 + time * 0.9) * 0.45 + cos(qX2.y * 1.9 - time * 0.75) * 0.45 + sin((qX2.x + qX2.y) * 1.5 + time * 1.2) * 0.22 + cos(length(qX) * 2.2 - time * 1.4) * 0.14;\n  \n  vec2 qY = (p + eps.yx) + vec2(sin((p.y + eps.x) * 1.45 + time * 0.8), cos((p.x + eps.y) * 1.35 - time * 0.65)) * 0.55;\n  vec2 qY2 = (p + eps.yx) + vec2(cos(qY.y * 1.25 - time * 0.75), sin(qY.x * 1.4 + time * 0.85)) * 0.45;\n  float hY = sin(qY2.x * 1.8 + time * 0.9) * 0.45 + cos(qY2.y * 1.9 - time * 0.75) * 0.45 + sin((qY2.x + qY2.y) * 1.5 + time * 1.2) * 0.22 + cos(length(qY) * 2.2 - time * 1.4) * 0.14;\n  \n  vec2 grad = vec2(hX - h0, hY - h0) / eps.x;\n  vec3 normal = normalize(vec3(-grad * u_refract_depth * 0.42, 1.25));\n  \n  // Physical Snell-Law Wavelength Dispersion (Chromatic Aberration)\n  vec2 refrOffset = normal.xy * (u_dispersion * 1.4);\n  vec2 uvR = uv + refrOffset * 0.82;\n  vec2 uvG = uv + refrOffset * 1.0;\n  vec2 uvB = uv + refrOffset * 1.22;\n  \n  // Deep Optical Studio Backdrop\n  float r0 = length(uv);\n  vec3 studioBase = mix(u_colorC, u_colorC * 1.6 + vec3(0.02, 0.03, 0.06), smoothstep(1.4, 0.0, r0));\n  \n  // Multi-band chromatic light streams in the optical background\n  float b1R = smoothstep(0.65, 0.0, abs(uvR.x * 1.2 - 0.2 + sin(uvR.y * 2.0 + time * 0.3) * 0.25));\n  float b2R = smoothstep(0.75, 0.0, abs(uvR.y * 1.2 + 0.15 - cos(uvR.x * 1.8 - time * 0.25) * 0.22));\n  float bgR = mix(studioBase.r, u_colorA.r * 0.75, b1R * 0.6) + mix(0.0, u_colorB.r * 0.6, b2R * 0.55);\n  \n  float b1G = smoothstep(0.65, 0.0, abs(uvG.x * 1.2 - 0.2 + sin(uvG.y * 2.0 + time * 0.3) * 0.25));\n  float b2G = smoothstep(0.75, 0.0, abs(uvG.y * 1.2 + 0.15 - cos(uvG.x * 1.8 - time * 0.25) * 0.22));\n  float bgG = mix(studioBase.g, u_colorA.g * 0.75, b1G * 0.6) + mix(0.0, u_colorB.g * 0.6, b2G * 0.55);\n  \n  float b1B = smoothstep(0.65, 0.0, abs(uvB.x * 1.2 - 0.2 + sin(uvB.y * 2.0 + time * 0.3) * 0.25));\n  float b2B = smoothstep(0.75, 0.0, abs(uvB.y * 1.2 + 0.15 - cos(uvB.x * 1.8 - time * 0.25) * 0.22));\n  float bgB = mix(studioBase.b, u_colorA.b * 0.75, b1B * 0.6) + mix(0.0, u_colorB.b * 0.6, b2B * 0.55);\n  \n  vec3 refractedScene = vec3(bgR, bgG, bgB);\n  \n  // Physical Beer-Lambert Transmission Tint through liquid glass body\n  float thickness = clamp(0.6 + h0 * 0.45, 0.15, 1.5) * u_refract_depth;\n  vec3 tintAbsorption = exp(-thickness * mix(vec3(0.12, 0.08, 0.04), (vec3(1.0) - u_colorA * 0.4), 0.3));\n  refractedScene *= tintAbsorption;\n  \n  // Bounded Physical Caustics: Light focusing strictly at wave crests & curvature\n  float slopeMag = length(grad);\n  float causticFocal = exp(-pow(h0 * 1.8, 2.0) * 4.0) * pow(clamp(slopeMag * 0.75, 0.0, 1.0), 1.8);\n  causticFocal *= u_caustic_power;\n  vec3 causticColor = mix(vec3(0.9, 0.95, 1.0), u_colorA, 0.35) * causticFocal * 0.75;\n  \n  // Fresnel Reflection & Studio Softbox Specular\n  vec3 viewDir = vec3(0.0, 0.0, 1.0);\n  float cosTheta = clamp(dot(normal, viewDir), 0.0, 1.0);\n  float fresnel = pow(1.0 - cosTheta, 3.8);\n  \n  vec3 light1 = normalize(vec3(0.5, 0.7, 0.85));\n  vec3 light2 = normalize(vec3(-0.65, -0.4, 0.75));\n  vec3 h1 = normalize(light1 + viewDir);\n  vec3 h2 = normalize(light2 + viewDir);\n  \n  float spec1 = pow(max(dot(normal, h1), 0.0), 42.0);\n  float spec2 = pow(max(dot(normal, h2), 0.0), 20.0) * 0.45;\n  float totalSpec = (spec1 + spec2) * (0.9 + 0.3 * u_refract_depth);\n  \n  // Energy-conserving composite (strictly bounded, immune to blowout)\n  vec3 reflectionColor = mix(vec3(1.0), u_colorB, 0.25);\n  vec3 col = mix(refractedScene, reflectionColor, fresnel * 0.65);\n  col += causticColor;\n  col += vec3(1.0, 0.98, 0.96) * totalSpec * 1.1;\n  \n  col = tanh(col * 1.12);\n  return col;\n}\n\n\nvec3 gradeColor(vec3 c){\n  c = (c - 0.5) * u_contrast + 0.5;\n  c *= u_brightness;\n  float maxVal = max(c.r, max(c.g, c.b));\n  vec3 norm = maxVal > 1.0 ? c / maxVal : c;\n  vec3 h = rgb2hsv(clamp(norm, 0.0, 1.0));\n  h.x = fract(h.x + u_hue);\n  h.y = clamp(h.y * u_saturation, 0.0, 2.0);\n  vec3 res = hsv2rgb(h);\n  return maxVal > 1.0 ? res * maxVal : res;\n}\n\n\n\n\nvec3 sampleGraded(vec2 uv){\n  vec3 scene = renderScene(uv);\n  vec3 col = gradeColor(scene);\n  return col;\n}\n\nvec3 tonemapACES(vec3 x){\n  float a = 2.51, b = 0.03, c = 2.43, d = 0.59, e = 0.14;\n  return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);\n}\nvec3 applyTonemap(vec3 col){\n  return tonemapACES(col * max(u_exposure, 0.01));\n}\n\n\nvoid main(){\n  float uvScale = max(1.0 / u_resolution.y, (16.0 / 9.0) / u_resolution.x);\n  vec2 uv = (gl_FragCoord.xy - 0.5 * u_resolution.xy) * uvScale;\n\n  vec3 col = sampleGraded(uv);\n\n  col = applyTonemap(col);\n  fragColor = vec4(col, 1.0);\n}";

const VERT = `#version 300 es
layout(location = 0) in vec2 a_pos;
void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }`;

function hexToRgb(hex: string): [number, number, number] {
  const c = hex.replace('#', '');
  const n = parseInt(c.length === 3 ? c.split('').map(x => x + x).join('') : c, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

export function PrismaticLiquidGlassCard({
  logoSrc = "",
  imageSrc = "",
  colorA = "#006aea",
  colorB = "#ff2e9c",
  colorC = "#eef3fb",
  speed = 0.65,
  interactive = false,
  tilt = false,
  className = "",
  style = {}
}: PrismaticLiquidGlassCardProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    if (!container || !canvas) return;

    const gl = canvas.getContext('webgl2', { antialias: false, powerPreference: 'high-performance' });
    if (!gl) return;

    canvas.addEventListener('webglcontextlost', (e) => e.preventDefault(), false);

    const compile = (type: number, src: string) => {
      const s = gl.createShader(type);
      if (!s) return null;
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
        console.error('[Shader Studio Error]', gl.getShaderInfoLog(s));
        gl.deleteShader(s);
        return null;
      }
      return s;
    };

    const vs = compile(gl.VERTEX_SHADER, VERT);
    const fs = compile(gl.FRAGMENT_SHADER, FRAG);
    if (!vs || !fs) return;

    const prog = gl.createProgram();
    if (!prog) return;
    gl.attachShader(prog, vs);
    gl.attachShader(prog, fs);
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
      console.error('[Shader Studio Link Error]', gl.getProgramInfoLog(prog));
      gl.deleteProgram(prog);
      return;
    }
    gl.useProgram(prog);

    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    const uniforms: Record<string, number | [number, number, number]> = {
      u_glass_scale: 1.6,
      u_dispersion: 0.057,
      u_liquid_flow: 1.35,
      u_caustic_power: 1.6,
      u_refract_depth: 2.2,
      u_speed: 1,
      u_scale: 1,
      u_rotation: 0,
      u_cx: 0,
      u_cy: 0,
      u_exposure: 1,
      u_hue: 0,
      u_saturation: 1.55,
      u_brightness: 1,
      u_contrast: 1.15,
      u_colorA: [0, 0.9176470588235294, 0.996078431372549],
      u_colorB: [0.9882352941176471, 0.1607843137254902, 0.9254901960784314],
      u_colorC: [0.7607843137254902, 0.7764705882352941, 1],
    };

    const locs: Record<string, WebGLUniformLocation | null> = {
      u_time: gl.getUniformLocation(prog, 'u_time'),
      u_resolution: gl.getUniformLocation(prog, 'u_resolution'),
      u_mouse: gl.getUniformLocation(prog, 'u_mouse'),
      u_speed: gl.getUniformLocation(prog, 'u_speed'),
      u_colorA: gl.getUniformLocation(prog, 'u_colorA'),
      u_colorB: gl.getUniformLocation(prog, 'u_colorB'),
      u_colorC: gl.getUniformLocation(prog, 'u_colorC'),
      u_mediaTexture: gl.getUniformLocation(prog, 'u_mediaTexture'),
      u_mediaEnabled: gl.getUniformLocation(prog, 'u_mediaEnabled'),
      u_preserve_color: gl.getUniformLocation(prog, 'u_preserve_color'),
      u_mediaScale: gl.getUniformLocation(prog, 'u_mediaScale'),
      u_mediaRadius: gl.getUniformLocation(prog, 'u_mediaRadius'),
      u_mediaFeather: gl.getUniformLocation(prog, 'u_mediaFeather'),
      u_mediaResolution: gl.getUniformLocation(prog, 'u_mediaResolution'),
      u_mediaFlipX: gl.getUniformLocation(prog, 'u_mediaFlipX'),
      u_mediaFlipY: gl.getUniformLocation(prog, 'u_mediaFlipY'),
      u_mediaFit: gl.getUniformLocation(prog, 'u_mediaFit'),
    };

    Object.keys(uniforms).forEach(k => {
      if (!locs[k]) locs[k] = gl.getUniformLocation(prog, k);
    });

    const upload = (k: string, v: number | [number, number, number]) => {
      const loc = locs[k];
      if (!loc) return;
      if (Array.isArray(v)) gl.uniform3f(loc, v[0], v[1], v[2]);
      else gl.uniform1f(loc, v);
    };

    Object.keys(uniforms).forEach(k => upload(k, uniforms[k]));

    const mediaTex = gl.createTexture();
    let mediaLoaded = false;
    let mediaResolution = [1920, 1080];
    const mediaSrc = logoSrc || imageSrc || "";
    if (mediaSrc) {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        mediaResolution = [img.naturalWidth || img.width || 1920, img.naturalHeight || img.height || 1080];
        gl.activeTexture(gl.TEXTURE2);
        gl.bindTexture(gl.TEXTURE_2D, mediaTex);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
        mediaLoaded = true;
      };
      img.src = mediaSrc;
    }

    // Pre-upload colors once on mount to eliminate per-frame garbage collection
    const rgbA = hexToRgb(colorA);
    const rgbB = hexToRgb(colorB);
    const rgbC = hexToRgb(colorC);
    if (locs.u_colorA) gl.uniform3f(locs.u_colorA, rgbA[0], rgbA[1], rgbA[2]);
    if (locs.u_colorB) gl.uniform3f(locs.u_colorB, rgbB[0], rgbB[1], rgbB[2]);
    if (locs.u_colorC) gl.uniform3f(locs.u_colorC, rgbC[0], rgbC[1], rgbC[2]);

    const dpr = Math.min(typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1, 1.5);
    let sizeDirty = true;
    const updateSize = () => {
      const rect = container.getBoundingClientRect();
      const w = Math.max(1, Math.round(rect.width * dpr));
      const h = Math.max(1, Math.round(rect.height * dpr));
      if (canvas.width !== w || canvas.height !== h) {
        canvas.width = w;
        canvas.height = h;
        gl.viewport(0, 0, w, h);
        sizeDirty = true;
      }
    };
    updateSize();

    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(updateSize) : null;
    if (ro) ro.observe(container);

    const mouse = { x: 0, y: 0, tx: 0, ty: 0, down: 0 };
    const onPointerMove = (e: PointerEvent) => {
      if (!interactive) return;
      const rect = container.getBoundingClientRect();
      const normX = (e.clientX - rect.left - 0.5 * rect.width) / rect.height;
      const normY = -(e.clientY - rect.top - 0.5 * rect.height) / rect.height;
      mouse.tx = normX;
      mouse.ty = normY;

      if (tilt) {
        const tiltX = ((e.clientY - rect.top) / rect.height - 0.5) * -14;
        const tiltY = ((e.clientX - rect.left) / rect.width - 0.5) * 14;
        container.style.transition = 'transform 0.08s ease-out';
        container.style.transform = `perspective(1000px) rotateX(${tiltX.toFixed(2)}deg) rotateY(${tiltY.toFixed(2)}deg) scale3d(1.018, 1.018, 1.018)`;
      }
    };

    const onPointerLeave = () => {
      mouse.tx = 0;
      mouse.ty = 0;
      mouse.down = 0;
      if (tilt) {
        container.style.transition = 'transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1)';
        container.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)';
      }
    };

    const onPointerDown = () => { mouse.down = 1; };
    const onPointerUp = () => { mouse.down = 0; };

    container.addEventListener('pointermove', onPointerMove);
    container.addEventListener('pointerleave', onPointerLeave);
    container.addEventListener('pointerdown', onPointerDown);
    window.addEventListener('pointerup', onPointerUp);

    let isVisible = typeof document !== 'undefined' ? !document.hidden : true;
    let animId = 0;
    let lastT = performance.now();
    let simTime = 0;

    const render = (now: number) => {
      if (!isVisible) {
        animId = 0;
        return;
      }
      const dt = Math.min((now - lastT) * 0.001, 0.1);
      lastT = now;
      simTime += dt * speed;

      mouse.x += (mouse.tx - mouse.x) * 0.08;
      mouse.y += (mouse.ty - mouse.y) * 0.08;

      gl.useProgram(prog);
      if (locs.u_time) gl.uniform1f(locs.u_time, simTime);
      if (locs.u_resolution && sizeDirty) {
        gl.uniform2f(locs.u_resolution, canvas.width, canvas.height);
        sizeDirty = false;
      }
      if (locs.u_mouse) gl.uniform4f(locs.u_mouse, mouse.x, mouse.y, mouse.down, 0);
      if (locs.u_speed) gl.uniform1f(locs.u_speed, speed);
      if (locs.u_mediaTexture) {
        gl.activeTexture(gl.TEXTURE2);
        gl.bindTexture(gl.TEXTURE_2D, mediaTex);
        gl.uniform1i(locs.u_mediaTexture, 2);
      }
      if (locs.u_mediaEnabled) gl.uniform1f(locs.u_mediaEnabled, mediaLoaded ? 1 : 0);
      if (locs.u_mediaResolution) gl.uniform2f(locs.u_mediaResolution, mediaResolution[0], mediaResolution[1]);

      gl.drawArrays(gl.TRIANGLES, 0, 3);
      animId = requestAnimationFrame(render);
    };

    const startLoop = () => {
      if (!animId && isVisible) {
        lastT = performance.now();
        animId = requestAnimationFrame(render);
      }
    };

    const stopLoop = () => {
      if (animId) {
        cancelAnimationFrame(animId);
        animId = 0;
      }
    };

    const io = typeof IntersectionObserver !== 'undefined' ? new IntersectionObserver((entries) => {
      isVisible = (entries[0]?.isIntersecting ?? true) && !document.hidden;
      if (isVisible) startLoop();
      else stopLoop();
    }, { rootMargin: '100px' }) : null;
    if (io) io.observe(container);

    const onVisibility = () => {
      isVisible = !document.hidden;
      if (isVisible) startLoop();
      else stopLoop();
    };
    document.addEventListener('visibilitychange', onVisibility);

    startLoop();

    return () => {
      stopLoop();
      if (ro) ro.disconnect();
      if (io) io.disconnect();
      document.removeEventListener('visibilitychange', onVisibility);
      container.removeEventListener('pointermove', onPointerMove);
      container.removeEventListener('pointerleave', onPointerLeave);
      container.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('pointerup', onPointerUp);
      if (mediaTex) gl.deleteTexture(mediaTex);
      gl.deleteProgram(prog);
      gl.deleteBuffer(buf);
      if (vs) gl.deleteShader(vs);
      if (fs) gl.deleteShader(fs);
    };
  }, [logoSrc, imageSrc, colorA, colorB, colorC, speed, interactive, tilt]);

  return (
    <div
      ref={containerRef}
      className={className}
      aria-hidden="true"
      style={{
        position: 'absolute',
        inset: 0,
        width: '100%',
        height: '100%',
        overflow: 'hidden',
        backgroundColor: colorC,
        pointerEvents: 'none',
        ...style
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          width: '100%',
          height: '100%',
          display: 'block',
          position: 'absolute',
          inset: 0
        }}
      />
          </div>
  );
}

export default PrismaticLiquidGlassCard;
